77	func TestRegisterBasicChainAndConsistency(t *testing.T) {
78		graph := map[string]*Lineage{}
79		mustRegister(t, graph, "raw")
80		mustRegister(t, graph, "detail", "raw")
81		mustRegister(t, graph, "summary", "detail")
82	
83		assertEntry(t, graph, "raw", nil, []string{"detail"})
84		assertEntry(t, graph, "detail", []string{"raw"}, []string{"summary"})
85		assertEntry(t, graph, "summary", []string{"detail"}, nil)
86		assertConsistent(t, graph)
87	
88		if got, want := Roots(graph), []string{"raw"}; !reflect.DeepEqual(got, want) {
89			t.Errorf("Roots = %v, want %v", got, want)
90		}
91	}
