93	// The scenario from the spec: re-registering detail while still using raw must
94	// succeed even though raw is detail's existing upstream.
95	func TestReregisterKeepsExistingUpstream(t *testing.T) {
96		graph := map[string]*Lineage{}
97		mustRegister(t, graph, "raw")
98		mustRegister(t, graph, "detail", "raw")
99		mustRegister(t, graph, "summary", "detail")
100	
101		mustRegister(t, graph, "detail", "raw")
102		assertEntry(t, graph, "raw", nil, []string{"detail"})
103		assertEntry(t, graph, "detail", []string{"raw"}, []string{"summary"})
104		assertEntry(t, graph, "summary", []string{"detail"}, nil)
105		assertConsistent(t, graph)
106	
107		// Same registration again: still successful, nothing changes.
108		before := snapshot(graph)
109		mustRegister(t, graph, "detail", "raw")
110		if !reflect.DeepEqual(snapshot(graph), before) {
111			t.Fatalf("identical re-registration changed graph: before=%v after=%v", before, snapshot(graph))
112		}
113	}
114	
115	// Pointing raw at summary closes raw -> summary -> detail -> raw.
116	func TestCycleAcrossMultipleLevelsRejected(t *testing.T) {
117		graph := map[string]*Lineage{}
118		mustRegister(t, graph, "raw")
119		mustRegister(t, graph, "detail", "raw")
120		mustRegister(t, graph, "summary", "detail")
121	
122		before := snapshot(graph)
123		err := Register(graph, Dataset{Name: "raw"}, []string{"summary"})
124		if err == nil {
125			t.Fatal("expected cycle error, got nil")
126		}
127		if !strings.Contains(err.Error(), "cycle") || !strings.Contains(err.Error(), "summary") {
128			t.Errorf("error %q should mention a cycle and the related name summary", err.Error())
129		}
130		if !reflect.DeepEqual(snapshot(graph), before) {
131			t.Fatalf("failed registration changed graph: before=%v after=%v", before, snapshot(graph))
132		}
133		assertEntry(t, graph, "raw", nil, []string{"detail"})
134		assertConsistent(t, graph)
135	}
