196	// Duplicate parent names collapse to one entry, first occurrence wins, and the
197	// declared list order is the stored order.
198	func TestDuplicateUpstreamsDedupedFirstWins(t *testing.T) {
199		graph := map[string]*Lineage{}
200		mustRegister(t, graph, "a")
201		mustRegister(t, graph, "b")
202		mustRegister(t, graph, "c")
203		mustRegister(t, graph, "d", "b", "a", "b", "c", "a")
204	
205		assertEntry(t, graph, "d", []string{"b", "a", "c"}, nil)
206		assertEntry(t, graph, "a", nil, []string{"d"})
207		assertEntry(t, graph, "b", nil, []string{"d"})
208		assertEntry(t, graph, "c", nil, []string{"d"})
209		assertConsistent(t, graph)
210	
211		// Re-registering with duplicates is repeatedly idempotent.
212		before := snapshot(graph)
213		mustRegister(t, graph, "d", "b", "a", "b", "c", "a")
214		mustRegister(t, graph, "d", "b", "a", "b", "c", "a")
215		if !reflect.DeepEqual(snapshot(graph), before) {
216			t.Fatal("idempotent re-registration changed the graph")
217		}
218	}
