220	// New children land at the end of an upstream's child list; existing relative
221	// order is untouched.
222	func TestNewDownstreamAppendedAtEnd(t *testing.T) {
223		graph := map[string]*Lineage{}
224		mustRegister(t, graph, "p")
225		mustRegister(t, graph, "first", "p")
226		mustRegister(t, graph, "second", "p")
227	
228		mustRegister(t, graph, "late", "p")
229		assertEntry(t, graph, "p", nil, []string{"first", "second", "late"})
230	
231		// Re-registering first must not move it.
232		mustRegister(t, graph, "first", "p")
233		assertEntry(t, graph, "p", nil, []string{"first", "second", "late"})
234		assertConsistent(t, graph)
235	}
