237	// Empty upstream list turns the dataset into a root: reverse edges removed,
238	// downstreams retained; Roots updates and stays name-sorted.
239	func TestEmptyUpstreamsBecomesRoot(t *testing.T) {
240		graph := map[string]*Lineage{}
241		mustRegister(t, graph, "raw")
242		mustRegister(t, graph, "other")
243		mustRegister(t, graph, "mid", "raw", "other")
244		mustRegister(t, graph, "leaf", "mid")
245	
246		mustRegister(t, graph, "mid") // no upstreams now
247		assertEntry(t, graph, "mid", nil, []string{"leaf"})
248		assertEntry(t, graph, "raw", nil, nil)
249		assertEntry(t, graph, "other", nil, nil)
250		assertEntry(t, graph, "leaf", []string{"mid"}, nil)
251		assertConsistent(t, graph)
252	
253		if got, want := Roots(graph), []string{"mid", "other", "raw"}; !reflect.DeepEqual(got, want) {
254			t.Errorf("Roots = %v, want %v", got, want)
255		}
256	}
