258	// A failure partway through the list leaves no new node and no partial reverse
259	// edges, even when a valid parent precedes the offending one.
260	func TestFailureIsAtomicWithValidParentFirst(t *testing.T) {
261		graph := map[string]*Lineage{}
262		mustRegister(t, graph, "p")
263		mustRegister(t, graph, "p2")
264		mustRegister(t, graph, "existing", "p")
265		before := snapshot(graph)
266	
267		err := Register(graph, Dataset{Name: "newkid"}, []string{"p", "ghost"})
268		if err == nil || !strings.Contains(err.Error(), "ghost") {
269			t.Fatalf("want unknown-parent error naming ghost, got %v", err)
270		}
271		if _, ok := graph["newkid"]; ok {
272			t.Error("failed registration left new node newkid in graph")
273		}
274		if !reflect.DeepEqual(snapshot(graph), before) {
275			t.Fatalf("graph changed after failure: before=%v after=%v", before, snapshot(graph))
276		}
277		assertEntry(t, graph, "p", nil, []string{"existing"})
278		assertConsistent(t, graph)
279	
280		// Self reference after a valid parent is likewise atomic.
281		err = Register(graph, Dataset{Name: "loop"}, []string{"p2", "loop"})
282		if err == nil || !strings.Contains(err.Error(), "its own parent") {
283			t.Fatalf("want self-parent error, got %v", err)
284		}
285		if _, ok := graph["loop"]; ok {
286			t.Error("failed self-parent registration left node in graph")
287		}
288		if !reflect.DeepEqual(snapshot(graph), before) {
289			t.Fatalf("graph changed after self-parent failure")
290		}
291	
292		// After fixing the request, the dataset registers normally.
293		mustRegister(t, graph, "newkid", "p", "p2")
294		assertEntry(t, graph, "newkid", []string{"p", "p2"}, nil)
295		assertConsistent(t, graph)
296	}
