298	// Rejected re-registration of an existing node preserves its old content and
299	// every other node.
300	func TestFailedReregisterPreservesOldEdges(t *testing.T) {
301		graph := map[string]*Lineage{}
302		mustRegister(t, graph, "raw")
303		mustRegister(t, graph, "mid", "raw")
304		mustRegister(t, graph, "top", "mid")
305		before := snapshot(graph)
306	
307		if err := Register(graph, Dataset{Name: "mid"}, []string{"top"}); err == nil {
308			t.Fatal("expected cycle rejection on re-register")
309		}
310		if !reflect.DeepEqual(snapshot(graph), before) {
311			t.Fatalf("failed re-registration changed graph: before=%v after=%v", before, snapshot(graph))
312		}
313	
314		if err := Register(graph, Dataset{Name: "mid"}, []string{"missing"}); err == nil {
315			t.Fatal("expected unknown-parent rejection on re-register")
316		}
317		if !reflect.DeepEqual(snapshot(graph), before) {
318			t.Fatalf("failed re-registration changed graph: before=%v after=%v", before, snapshot(graph))
319		}
320		assertConsistent(t, graph)
321	}
