323	func TestValidationErrors(t *testing.T) {
324		graph := map[string]*Lineage{}
325		mustRegister(t, graph, "a")
326	
327		if err := Register(graph, Dataset{}, []string{"a"}); err == nil ||
328			!strings.Contains(err.Error(), "name is required") {
329			t.Fatalf("empty name: want required-name error, got %v", err)
330		}
331	
332		err := Register(graph, Dataset{Name: "b"}, []string{"a", "nope"})
333		if err == nil || !strings.Contains(err.Error(), "unknown parent nope") {
