335		}
336	
337		err = Register(graph, Dataset{Name: "b"}, []string{"b"})
338		if err == nil || !strings.Contains(err.Error(), "b") {
339			t.Fatalf("self parent: want error naming b, got %v", err)
340		}
341		if _, ok := graph["b"]; ok {
342			t.Error("self-parent failure must not create the node")
