346	// With several problems in one list, the first in input order is reported.
347	func TestFirstProblemInInputOrderReported(t *testing.T) {
348		graph := map[string]*Lineage{}
349		mustRegister(t, graph, "a")
350		// top -> down, so registering top with parent down closes a cycle.
351		mustRegister(t, graph, "top")
352		mustRegister(t, graph, "down", "top")
353	
354		cases := []struct {
355			name    string
356			dataset string
357			parents []string
358			want    string
359		}{
360			{"unknown before self", "n", []string{"ghost", "n"}, "ghost"},
361			{"self before unknown", "n", []string{"n", "ghost"}, "its own parent"},
362			{"cycle before unknown", "top", []string{"down", "ghost"}, "cycle"},
363			{"unknown before cycle", "top", []string{"ghost", "down"}, "ghost"},
364		}
365		for _, tc := range cases {
366			t.Run(tc.name, func(t *testing.T) {
367				err := Register(graph, Dataset{Name: tc.dataset}, tc.parents)
368				if err == nil || !strings.Contains(err.Error(), tc.want) {
369					t.Fatalf("parents %v: want error containing %q, got %v", tc.parents, tc.want, err)
370				}
371			})
372		}
373	}
