375	// Mutating the caller's slice after a successful Register must not affect the
376	// stored graph.
377	func TestCallerSliceMutationIsolated(t *testing.T) {
378		graph := map[string]*Lineage{}
379		mustRegister(t, graph, "a")
380		mustRegister(t, graph, "b")
381	
382		parents := []string{"a", "b"}
383		mustRegister(t, graph, "d", parents...)
384		parents[0] = "tampered"
385		parents = append(parents, "extra")
386	
387		assertEntry(t, graph, "d", []string{"a", "b"}, nil)
388		assertConsistent(t, graph)
389	}
