391	// Roots is sorted by name even when datasets were registered out of order.
392	func TestRootsSorted(t *testing.T) {
393		graph := map[string]*Lineage{}
394		mustRegister(t, graph, "zeta")
395		mustRegister(t, graph, "alpha")
396		mustRegister(t, graph, "mid", "alpha")
397		mustRegister(t, graph, "beta")
398	
399		if got, want := Roots(graph), []string{"alpha", "beta", "zeta"}; !reflect.DeepEqual(got, want) {
400			t.Errorf("Roots = %v, want %v", got, want)
401		}
402	}
403	
404	type snap struct {
405		parents  map[string][]string
406		children map[string][]string
407	}
408	
409	func snapshot(graph map[string]*Lineage) snap {
410		s := snap{map[string][]string{}, map[string][]string{}}
411		for name, e := range graph {
412			s.parents[name] = append([]string(nil), e.Parents...)
413			s.children[name] = append([]string(nil), e.Children...)
414		}
415		return s
416	}
